// Package oauth holds provider configurations and OAuth exchange helpers.
package oauth

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/github"
	"golang.org/x/oauth2/google"
)

// UserInfo holds the normalized profile returned after a successful OAuth exchange.
type UserInfo struct {
	ProviderSub   string
	Email         string
	EmailVerified bool
	DisplayName   string
	AvatarURL     string
}

// Provider abstracts a single OAuth 2.0 identity provider.
type Provider interface {
	// Name returns the provider identifier ("google" or "github").
	Name() string
	// AuthCodeURL generates the redirect URL for the OAuth Authorization Code flow.
	AuthCodeURL(state string, opts ...oauth2.AuthCodeOption) string
	// Exchange trades the authorization code for tokens.
	Exchange(ctx context.Context, code string) (*oauth2.Token, error)
	// FetchUserInfo retrieves the user profile using the given access token.
	FetchUserInfo(ctx context.Context, token *oauth2.Token) (*UserInfo, error)
}

// Config holds provider credentials and the callback base URL.
type Config struct {
	GoogleClientID     string
	GoogleClientSecret string
	GitHubClientID     string
	GitHubClientSecret string
	RedirectBaseURL    string
}

// NewProviders returns the configured Google and GitHub providers.
func NewProviders(cfg Config) map[string]Provider {
	googleCfg := &oauth2.Config{
		ClientID:     cfg.GoogleClientID,
		ClientSecret: cfg.GoogleClientSecret,
		RedirectURL:  cfg.RedirectBaseURL + "/auth/google/callback",
		Scopes:       []string{"openid", "email", "profile"},
		Endpoint:     google.Endpoint,
	}

	githubCfg := &oauth2.Config{
		ClientID:     cfg.GitHubClientID,
		ClientSecret: cfg.GitHubClientSecret,
		RedirectURL:  cfg.RedirectBaseURL + "/auth/github/callback",
		Scopes:       []string{"read:user", "user:email"},
		Endpoint:     github.Endpoint,
	}

	return map[string]Provider{
		"google": &googleProvider{cfg: googleCfg},
		"github": &githubProvider{cfg: githubCfg},
	}
}

// ─────────────────────────────────────────────
// Google
// ─────────────────────────────────────────────

type googleProvider struct {
	cfg *oauth2.Config
}

func (g *googleProvider) Name() string { return "google" }

func (g *googleProvider) AuthCodeURL(state string, opts ...oauth2.AuthCodeOption) string {
	return g.cfg.AuthCodeURL(state, opts...)
}

func (g *googleProvider) Exchange(ctx context.Context, code string) (*oauth2.Token, error) {
	return g.cfg.Exchange(ctx, code)
}

// googleUserInfo is the subset of Google's userinfo endpoint we need.
type googleUserInfo struct {
	Sub           string `json:"sub"`
	Email         string `json:"email"`
	EmailVerified bool   `json:"email_verified"`
	Name          string `json:"name"`
	Picture       string `json:"picture"`
}

func (g *googleProvider) FetchUserInfo(ctx context.Context, token *oauth2.Token) (*UserInfo, error) {
	client := g.cfg.Client(ctx, token)
	resp, err := client.Get("https://www.googleapis.com/oauth2/v3/userinfo")
	if err != nil {
		return nil, fmt.Errorf("google userinfo: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("google userinfo: unexpected status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("google userinfo: read body: %w", err)
	}
	var info googleUserInfo
	if err := json.Unmarshal(body, &info); err != nil {
		return nil, fmt.Errorf("google userinfo: decode: %w", err)
	}
	return &UserInfo{
		ProviderSub:   info.Sub,
		Email:         info.Email,
		EmailVerified: info.EmailVerified,
		DisplayName:   info.Name,
		AvatarURL:     info.Picture,
	}, nil
}

// ─────────────────────────────────────────────
// GitHub
// ─────────────────────────────────────────────

type githubProvider struct {
	cfg *oauth2.Config
}

func (g *githubProvider) Name() string { return "github" }

func (g *githubProvider) AuthCodeURL(state string, opts ...oauth2.AuthCodeOption) string {
	return g.cfg.AuthCodeURL(state, opts...)
}

func (g *githubProvider) Exchange(ctx context.Context, code string) (*oauth2.Token, error) {
	return g.cfg.Exchange(ctx, code)
}

// githubUser is the response from GET /user.
type githubUser struct {
	ID        int64  `json:"id"`
	Login     string `json:"login"`
	Name      string `json:"name"`
	AvatarURL string `json:"avatar_url"`
	Email     string `json:"email"`
}

// githubEmail is one entry from GET /user/emails.
type githubEmail struct {
	Email    string `json:"email"`
	Primary  bool   `json:"primary"`
	Verified bool   `json:"verified"`
}

func (g *githubProvider) FetchUserInfo(ctx context.Context, token *oauth2.Token) (*UserInfo, error) {
	client := g.cfg.Client(ctx, token)

	// Fetch profile.
	user, err := fetchGitHubUser(ctx, client)
	if err != nil {
		return nil, err
	}

	// Fetch emails to find the primary verified one.
	email, verified, err := fetchGitHubPrimaryEmail(ctx, client)
	if err != nil {
		// Fall back to the profile email if the emails endpoint fails.
		email = user.Email
		verified = false
	}
	if email == "" {
		email = user.Email
	}

	displayName := user.Name
	if displayName == "" {
		displayName = user.Login
	}

	return &UserInfo{
		ProviderSub:   fmt.Sprintf("%d", user.ID),
		Email:         email,
		EmailVerified: verified,
		DisplayName:   displayName,
		AvatarURL:     user.AvatarURL,
	}, nil
}

func fetchGitHubUser(ctx context.Context, client *http.Client) (*githubUser, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://api.github.com/user", nil)
	if err != nil {
		return nil, fmt.Errorf("github /user: %w", err)
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("github /user: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("github /user: unexpected status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("github /user: read body: %w", err)
	}
	var u githubUser
	if err := json.Unmarshal(body, &u); err != nil {
		return nil, fmt.Errorf("github /user: decode: %w", err)
	}
	return &u, nil
}

func fetchGitHubPrimaryEmail(ctx context.Context, client *http.Client) (email string, verified bool, err error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://api.github.com/user/emails", nil)
	if err != nil {
		return "", false, fmt.Errorf("github /user/emails: %w", err)
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := client.Do(req)
	if err != nil {
		return "", false, fmt.Errorf("github /user/emails: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", false, fmt.Errorf("github /user/emails: unexpected status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", false, fmt.Errorf("github /user/emails: read body: %w", err)
	}
	var emails []githubEmail
	if err := json.Unmarshal(body, &emails); err != nil {
		return "", false, fmt.Errorf("github /user/emails: decode: %w", err)
	}
	for _, e := range emails {
		if e.Primary {
			return e.Email, e.Verified, nil
		}
	}
	if len(emails) > 0 {
		return emails[0].Email, emails[0].Verified, nil
	}
	return "", false, nil
}

