package httpapi

import (
	"bytes"
	"encoding/gob"
	"fmt"

	"github.com/google/uuid"
)

// scsSessionData mirrors the internal structure scs uses to gob-encode session
// values. The "values" map stores key → value pairs using a codec; scs defaults
// to encoding/gob with the registered type map.
//
// scs stores the session as a gob-encoded map[string]interface{}.
// We only need to extract the "user_id" string key.
type scsSessionData struct {
	Values  map[string]interface{}
	Expiry  interface{}
	Status  interface{}
	Token   interface{}
}

// extractUserIDFromSessionData decodes the gob payload written by scs and
// returns the "user_id" value. Returns uuid.Nil if the key is absent.
func extractUserIDFromSessionData(data []byte) (uuid.UUID, error) {
	// Register string type to avoid gob "type not registered" panic.
	gob.Register(map[string]interface{}{})

	dec := gob.NewDecoder(bytes.NewReader(data))

	// scs encodes session data as a map[string]interface{}.
	var values map[string]interface{}
	if err := dec.Decode(&values); err != nil {
		return uuid.Nil, fmt.Errorf("decode session gob: %w", err)
	}

	raw, ok := values["user_id"]
	if !ok {
		return uuid.Nil, nil
	}
	str, ok := raw.(string)
	if !ok {
		return uuid.Nil, fmt.Errorf("user_id is not a string: %T", raw)
	}
	id, err := uuid.Parse(str)
	if err != nil {
		return uuid.Nil, fmt.Errorf("parse user_id: %w", err)
	}
	return id, nil
}

